1	import type { TraversalExecutionState } from '@core/TraversalExecution';
2	import type { VertexTypes } from '@core/TreeTypeParameters';
3	import { inspectDagMilestones } from './inspectDag';
4	import type { AsyncDagTraversalRunner } from './lib/AsyncDagTraversalRunner';
5	import type { DagMilestoneSnapshot } from './lib/DagInspection';
6	import type {
7	  DagDeferredWork,
8	  DagSettlementOutcome,
9	  DagSummary,
10	} from './lib/DagProgress';
11	import { dagRunnerCapabilities } from './lib/dagRunnerCapabilities';
12	import type { DagTraversalRunner } from './lib/DagTraversalRunner';
13	
14	/** Declaration only: issued objects use WeakMap ownership, with no constructor value. */
15	declare class NominalDagWorkTicket<ID> {
16	  private constructor();
17	  private readonly ticketIdentity: never;
18	  readonly vertexId: ID;
19	}
20	
21	/** Local settlement capability issued by one coordinator; copying loses ownership. */
22	export type DagWorkTicket<ID = unknown> = NominalDagWorkTicket<ID>;
23	
24	export type DagWorkBoundary<ID = unknown> =
25	  | Readonly<{
26	      kind: 'awaitingSettlement';
27	      workTickets: readonly DagWorkTicket<ID>[];
28	    }>
29	  | Readonly<{ kind: 'paused' }>
30	  | Readonly<{ kind: 'finished' }>;
31	
32	export type DagSettlementReceipt =
33	  | Readonly<{ kind: 'accepted' }>
34	  | Readonly<{ kind: 'alreadyAccepted' }>;
35	
36	interface DagCoordinationControl<ID> extends TraversalExecutionState {
37	  completeWork(ticket: DagWorkTicket<ID>): DagSettlementReceipt;
38	  /** Fatal for the whole traversal; keep retryable work deferred instead. */
39	  failTraversal(
40	    ticket: DagWorkTicket<ID>,
41	    error: unknown,
42	  ): DagSettlementReceipt;
43	  /** Capture dependency explanations without advancing the coordinated runner. */
44	  inspectMilestones(): DagMilestoneSnapshot<ID>;
45	  summary(): DagSummary<ID>;
46	  requestPause(): boolean;
47	}
48	
49	export interface DagWorkSession<ID = unknown>
50	  extends DagCoordinationControl<ID> {
51	  advance(): DagWorkBoundary<ID>;
52	}
53	
54	export interface AsyncDagWorkSession<ID = unknown>
55	  extends DagCoordinationControl<ID> {
56	  advance(): Promise<DagWorkBoundary<ID>>;
57	}
58	
59	type SettlementRunner<ID> = Pick<
60	  DagTraversalRunner<VertexTypes, VertexTypes, ID>,
61	  | 'settle'
62	  | 'summary'
63	  | 'requestPause'
64	  | 'getStopReason'
65	  | 'getStatus'
66	  | 'isHalted'
67	  | 'inspect'
68	>;
69	
70	function makeCoordination<ID>(
71	  runner: SettlementRunner<ID>,
72	  inspectDependencies: () => DagMilestoneSnapshot<ID>,
73	) {
74	  if (
75	    dagRunnerCapabilities.get(runner)?.workCompletion !== 'externalSettlement'
76	  ) {
77	    throw new TypeError(
78	      'DAG coordination requires externalSettlement work completion',
79	    );
80	  }
81	  const tickets = new WeakMap<DagWorkTicket<ID>, DagDeferredWork<ID>>();
82	  const settle = (
83	    ticket: DagWorkTicket<ID>,
84	    outcome: DagSettlementOutcome,
85	  ): DagSettlementReceipt => {
86	    const work = tickets.get(ticket);
87	    if (work === undefined) {
88	      throw new TypeError('Unknown or foreign DAG work ticket');
89	    }
90	    return {
91	      kind: runner.settle(work.vertexId, outcome, work.generation)
92	        ? 'accepted'
93	        : 'alreadyAccepted',
94	    };
95	  };
96	  const failTraversal = (ticket: DagWorkTicket<ID>, error: unknown) =>
97	    settle(ticket, { kind: 'traversalFailed', error });
98	  return {
99	    completeWork: (ticket: DagWorkTicket<ID>) =>
100	      settle(ticket, { kind: 'workCompleted' }),
101	    failTraversal,
102	    getStatus: () => runner.getStatus(),
103	    getStopReason: () => runner.getStopReason(),
104	    isHalted: () => runner.isHalted(),
105	    inspect: () => runner.inspect(),
106	    inspectMilestones: inspectDependencies,
107	    summary: () => runner.summary(),
108	    requestPause: () => runner.requestPause(),
109	    boundary: (): DagWorkBoundary<ID> => {
