40	export class DagTraversal<
41	  T extends VertexTypes = VertexTypes,
42	  R extends VertexTypes = T,
43	  ID = unknown,
44	> {
45	  private icfg: DagResolvedOptions<T, R, ID>;
46	  private visitors: DagTraversalVisitors<T, R, ID>;
47	  private readonly sourceMode: 'tree' | 'graph';
48	
49	  constructor(input: DagOptions<T, R, ID>) {
50	    assertNoConcurrency(input);
51	    assertPublicOptions(input, [...DAG_OPTION_KEYS]);
52	    const sources = captureDagSourcePatch(input);
53	    this.sourceMode = assertExactlyOneDagSource(sources);
54	    this.icfg = mergeDagTraversalInstanceConfigs(
55	      {
56	        ...(DAG_TRAVERSAL_DEFAULT_INSTANCE_CONFIG as unknown as DagResolvedOptions<
57	          T,
58	          R,
59	          ID
60	        >),
61	        ...sources,
62	      } as DagResolvedOptions<T, R, ID>,
63	      input,
64	      sources,
65	    );
66	    this.visitors = initDagVisitors(this.icfg);
67	  }
68	
69	  /**
70	   * Configure future runners. Own defined same-family sources replace; inherited
71	   * and own undefined sources retain the active source. Mode changes reject atomically.
72	   */
73	  configure(input: DagOptionsPatch<T, R, ID>): this {
74	    assertNoConcurrency(input);
75	    assertPublicOptions(input, [...DAG_OPTION_KEYS]);
76	    const sources = captureDagSourcePatch(input);
77	    if (
78	      (this.sourceMode === 'graph' && sources.traversableTree !== undefined) ||
79	      (this.sourceMode === 'tree' && sources.traversableGraph !== undefined)
80	    ) {
81	      throw new TypeError('DAG source mode cannot change after construction');
82	    }
83	    this.icfg = mergeDagTraversalInstanceConfigs(
84	      { ...this.icfg, visitors: this.visitors },
85	      input,
86	      sources,
87	    );
88	    this.visitors = initDagVisitors(this.icfg);
89	    return this;
90	  }
91	
92	  addVisitorFor<ORDER extends DagVisitorPhase>(
93	    order: ORDER,
94	    visitor: DagVisitor<T, R, NoInferPhase<ORDER>, ID>,
95	    options: Partial<TraversalVisitorFunctionOptions> = {},
96	  ): this {
97	    assertOwnKeys(options, ['priority', 'commandCommitMode']);
98	    (
99	      this.visitors as Record<
100	        ORDER,
101	        VisitorRecord<DagVisitor<T, R, ORDER, ID>>[]
102	      >
103	    )[order] = appendVisitorDefinition<DagVisitor<T, R, ORDER, ID>>(
104	      this.visitors[order] as VisitorRecord<DagVisitor<T, R, ORDER, ID>>[],
105	      { visitor, ...definedOptions(options) },
106	    );
107	    return this;
108	  }
109	
110	  addVisitorGroupFor<ORDER extends DagVisitorPhase>(
111	    order: ORDER,
112	    group: VisitorGroupDefinition<DagVisitor<T, R, NoInferPhase<ORDER>, ID>>,
113	  ): this {
114	    (
115	      this.visitors as Record<
116	        ORDER,
117	        VisitorRecord<DagVisitor<T, R, ORDER, ID>>[]
118	      >
119	    )[order] = appendVisitorGroup<DagVisitor<T, R, ORDER, ID>>(
120	      this.visitors[order] as VisitorRecord<DagVisitor<T, R, ORDER, ID>>[],
121	      group,
122	    );
123	    return this;
124	  }
125	
126	  listVisitorsFor<ORDER extends DagVisitorPhase>(
127	    order: ORDER,
128	  ): DagTraversalVisitors<T, R, ID>[ORDER] {
129	    return copyVisitorRecords(this.visitors[order]);
130	  }
131	
132	  setVisitorsFor<ORDER extends DagVisitorPhase>(
133	    order: ORDER,
134	    input: VisitorPhaseInput<DagVisitor<T, R, NoInferPhase<ORDER>, ID>>,
135	  ): this {
136	    (
137	      this.visitors as Record<
138	        ORDER,
139	        VisitorRecord<DagVisitor<T, R, ORDER, ID>>[]
140	      >
141	    )[order] = normalizeVisitorDefinitions<DagVisitor<T, R, ORDER, ID>>(input);
142	    return this;
143	  }
144	
145	  createRunner(): DagTraversalRunner<T, R, ID> {
146	    return new InternalDagTraversalRunner({
147	      ...this.icfg,
148	      visitors: this.visitors,
149	    });
150	  }
151	}
152	
153	function assertNoConcurrency(input: object): void {
154	  if (Object.prototype.hasOwnProperty.call(input, 'concurrency')) {
155	    throw new TypeError(
156	      'Synchronous DAG traversal does not accept concurrency',
157	    );
158	  }
