146	/** Validate a detached candidate before a facade commits any configuration. */
147	export function normalizeWalkOptions<Data, Edge, ID>(
148	  input: unknown,
149	  previous?: GraphWalkResolvedOptions<Data, Edge, ID>,
150	): GraphWalkResolvedOptions<Data, Edge, ID> {
151	  const value = object(input, 'Walking options must be an object');
152	  if (Object.prototype.hasOwnProperty.call(value, 'concurrency')) {
153	    throw new TypeError('Walking does not support a concurrency option');
154	  }
155	  const snapshot: Record<string, unknown> = {};
156	  const keys = [
157	    'source',
158	    'strategy',
159	    'revisit',
160	    'limits',
161	    'shouldFollowEdge',
162	    'shouldExpandVertex',
163	    'visitors',
164	    'emitEvents',
165	    'visitorPhases',
166	  ];
167	  assertOwnKeys(value, keys);
168	  for (const key of keys) {
169	    if (Object.prototype.hasOwnProperty.call(value, key))
170	      snapshot[key] = value[key];
171	  }
172	  const source =
173	    snapshot['source'] === undefined && previous !== undefined
174	      ? { ...previous.source }
175	      : captureSource<Data, Edge, ID>(snapshot['source']);
176	  const strategy =
177	    snapshot['strategy'] === undefined
178	      ? previous?.strategy ?? 'breadthFirst'
179	      : snapshot['strategy'];
180	  if (strategy !== 'breadthFirst' && strategy !== 'depthFirst') {
181	    throw new TypeError('Unknown walking strategy');
182	  }
183	  const revisit =
184	    snapshot['revisit'] === undefined
185	      ? previous?.revisit ?? 'once'
186	      : snapshot['revisit'];
187	  if (revisit !== 'once' && revisit !== 'simplePaths' && revisit !== 'walks') {
188	    throw new TypeError('Unknown walking revisit policy');
189	  }
190	  const limits = copyLimits(
191	    snapshot['limits'] === undefined
192	      ? previous?.limits ?? {}
193	      : snapshot['limits'],
194	  );
195	  if (
196	    revisit !== 'once' &&
197	    limits.maxDepth === undefined &&
198	    limits.maxCandidateReadAttempts === undefined
199	  ) {
200	    throw new TypeError(
201	      'Route enumeration requires maxDepth or maxCandidateReadAttempts',
202	    );
203	  }
204	  const shouldFollowEdge =
205	    snapshot['shouldFollowEdge'] === undefined
206	      ? previous?.shouldFollowEdge
207	      : snapshot['shouldFollowEdge'] === null
208	      ? undefined
209	      : snapshot['shouldFollowEdge'];
210	  const shouldExpandVertex =
211	    snapshot['shouldExpandVertex'] === undefined
212	      ? previous?.shouldExpandVertex
213	      : snapshot['shouldExpandVertex'] === null
214	      ? undefined
215	      : snapshot['shouldExpandVertex'];
216	  if (
217	    (shouldFollowEdge !== undefined &&
218	      typeof shouldFollowEdge !== 'function') ||
219	    (shouldExpandVertex !== undefined &&
220	      typeof shouldExpandVertex !== 'function')
221	  ) {
222	    throw new TypeError('Walking predicates must be callbacks');
223	  }
224	  const visitorInput =
225	    snapshot['visitors'] === undefined
226	      ? {}
227	      : object(snapshot['visitors'], 'Walking visitors must be a phase map');
